/**
 * A real QR code, not a decorative pattern — scanning it opens the site.
 *
 * Generated once with the `qrcode` package rather than at request time: the matrix for a
 * fixed URL never changes, so encoding it on every render would mean shipping an encoder into
 * the Worker to recompute a constant. Regenerate with:
 *
 *   node -e "…" (see the commit that added this file)
 *
 * Encodes: https://relaybird.haxzie.com
 */

export const QR_SIZE = 29

/** Row-major, one character per module. */
export const QR_BITS =
  ''
